content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --shibuya-color: #3b82f6;
  --shinjuku-color: #10b981;
  --ikebukuro-color: #f59e0b;

  /* 拡張性・ダークモード対応のための変数グループ */
  --scrollbar-thumb: #cbd5e1;
  --scrollbar-thumb-hover: #94a3b8;
  --scrollbar-track: #f1f5f9;
}

[data-theme="dark"] {
  --bg-color: #0f172a;
  --card-bg: #1e293b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --border-color: #334155;
  --scrollbar-thumb: #475569;
  --scrollbar-thumb-hover: #64748b;
  --scrollbar-track: #1e293b;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  transition: background-color 0.3s ease, color 0.3s ease;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

.header {
  margin-bottom: 2rem;
  text-align: center;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.5rem;
}

.subtitle {
  font-size: 1rem;
  color: var(--text-muted);
}

.main-content {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.chart-card {
  background-color: var(--card-bg);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--border-color);
  align-items: center;
}

.checkbox-group {
  display: flex;
  gap: 1.25rem;
  flex-wrap: wrap;
}

.checkbox-label {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  user-select: none;
}

.checkbox-label input[type="checkbox"] {
  width: 1.15rem;
  height: 1.15rem;
  accent-color: var(--primary-color);
  cursor: pointer;
}

.table-container {
  background-color: var(--card-bg);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  overflow-x: auto;
}

/* カスタムスクロールバーのスタイリング */
.table-container::-webkit-scrollbar {
  height: 8px;
}

.table-container::-webkit-scrollbar-track {
  background: var(--scrollbar-track);
  border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb {
  background: var(--scrollbar-thumb);
  border-radius: 4px;
}

.table-container::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover);
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 0.95rem;
}

.data-table th,
.data-table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--border-color);
}

.data-table th {
  background-color: var(--scrollbar-track);
  font-weight: 600;
  color: var(--text-main);
}

.data-table tbody tr:hover {
  background-color: var(--bg-color);
}

.data-table td {
  color: var(--text-muted);
}

.data-table td:first-child {
  color: var(--text-main);
  font-weight: 500;
}

/* タブレット向けの中間ブレークポイント */
@media (max-width: 1024px) {
  .app-container {
    max-width: 100%;
    padding: 1.5rem 1rem;
  }
}

@media (max-width: 768px) {
  .app-container {
    padding: 1rem 0.5rem;
  }

  .title {
    font-size: 1.5rem;
  }

  .chart-card, .table-container {
    padding: 1rem;
  }
}

/**
 * 店舗名を表すユニオン型
 */
export type StoreName = '渋谷店' | '新宿店' | '池袋店';

/**
 * 月の文字列を表す型
 */
export type MonthString = '1月' | '2月' | '3月' | '4月' | '5月' | '6月' | '7月' | '8月' | '9月' | '10月' | '11月' | '12月';

/**
 * 月別来客数のデータ構造
 */
export interface MonthlyVisitor {
  /** 対象の月 */
  month: MonthString;
  /** 渋谷店の来客数 */
  渋谷店: number;
  /** 新宿店の来客数 */
  新宿店: number;
  /** 池袋店の来客数 */
  池袋店: number;
}

import { useState } from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { MonthlyVisitor } from './types';
import './index.css';

const initialData: MonthlyVisitor[] = [
  { month: '1月', 渋谷店: 4200, 新宿店: 3800, 池袋店: 2900 },
  { month: '2月', 渋谷店: 3900, 新宿店: 3500, 池袋店: 2700 },
  { month: '3月', 渋谷店: 4800, 新宿店: 4200, 池袋店: 3400 },
  { month: '4月', 渋谷店: 4500, 新宿店: 4000, 池袋店: 3200 },
  { month: '5月', 渋谷店: 5100, 新宿店: 4600, 池袋店: 3800 },
  { month: '6月', 渋谷店: 4700, 新宿店: 4300, 池袋店: 3500 },
  { month: '7月', 渋谷店: 5300, 新宿店: 4900, 池袋店: 4100 },
  { month: '8月', 渋谷店: 5800, 新宿店: 5200, 池袋店: 4500 },
  { month: '9月', 渋谷店: 4900, 新宿店: 4400, 池袋店: 3600 },
  { month: '10月', 渋谷店: 5200, 新宿店: 4700, 池袋店: 3900 },
  { month: '11月', 渋谷店: 5000, 新宿店: 4500, 池袋店: 3700 },
  { month: '12月', 渋谷店: 6100, 新宿店: 5500, 池袋店: 4800 },
];

const STORES = [
  { key: '渋谷店', colorVar: 'var(--shibuya-color)' },
  { key: '新宿店', colorVar: 'var(--shinjuku-color)' },
  { key: '池袋店', colorVar: 'var(--ikebukuro-color)' },
] as const;

export default function App() {
  const [visibleStores, setVisibleStores] = useState({
    渋谷店: true,
    新宿店: true,
    池袋店: true,
  });

  const handleToggle = (store: '渋谷店' | '新宿店' | '池袋店') => {
    setVisibleStores((prev) => ({
      ...prev,
      [store]: !prev[store],
    }));
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">店舗別 月別来客数比較</h1>
        <p className="subtitle">渋谷店・新宿店・池袋店の月ごとの来客数推移を確認できます</p>
      </header>

      <main className="main-content">
        <div className="chart-card">
          <div className="controls">
            <div className="checkbox-group">
              {STORES.map((store) => (
                <label key={store.key} className="checkbox-label" style={{ color: store.colorVar }}>
                  <input
                    type="checkbox"
                    checked={visibleStores[store.key]}
                    onChange={() => handleToggle(store.key)}
                  />
                  {store.key}
                </label>
              ))}
            </div>
          </div>

          <div style={{ width: '100%', height: 400 }}>
            <ResponsiveContainer>
              <LineChart data={initialData} margin={{ top: 10, right: 30, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="month" stroke="#64748b" />
                <YAxis stroke="#64748b" unit="人" />
                <Tooltip formatter={(value: number) => [`${value.toLocaleString()} 人`, '']} />
                <Legend />
                {visibleStores.渋谷店 && (
                  <Line
                    type="monotone"
                    dataKey="渋谷店"
                    stroke="var(--shibuya-color)"
                    strokeWidth={3}
                    dot={{ r: 4 }}
                    activeDot={{ r: 8 }}
                  />
                )}
                {visibleStores.新宿店 && (
                  <Line
                    type="monotone"
                    dataKey="新宿店"
                    stroke="var(--shinjuku-color)"
                    strokeWidth={3}
                    dot={{ r: 4 }}
                    activeDot={{ r: 8 }}
                  />
                )}
                {visibleStores.池袋店 && (
                  <Line
                    type="monotone"
                    dataKey="池袋店"
                    stroke="var(--ikebukuro-color)"
                    strokeWidth={3}
                    dot={{ r: 4 }}
                    activeDot={{ r: 8 }}
                  />
                )}
              </LineChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="table-container">
          <table className="data-table">
            <thead>
              <tr>
                <th>月</th>
                <th>渋谷店</th>
                <th>新宿店</th>
                <th>池袋店</th>
              </tr>
            </thead>
            <tbody>
              {initialData.map((row, index) => (
                <tr key={index}>
                  <td>{row.month}</td>
                  <td>{row.渋谷店.toLocaleString()} 人</td>
                  <td>{row.新宿店.toLocaleString()} 人</td>
                  <td>{row.池袋店.toLocaleString()} 人</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </main>
    </div>
  );
}
